// Generated by Parity for a migration. Serves the rebuilt app on 127.0.0.1: its screens, the records migrated
// from the legacy app (data/*.json, loaded into SQLite at start), and a small store for new records.
import { Database } from "bun:sqlite";
import { existsSync, readdirSync, readFileSync, realpathSync, statSync } from "node:fs";
import { join, sep } from "node:path";

const port = Number(process.env.PORT ?? 0);
const db = new Database(process.env.APP_DB ?? ":memory:", { strict: true });
db.exec(`CREATE TABLE IF NOT EXISTS data (entity TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL,
  body TEXT NOT NULL, PRIMARY KEY (entity, value));
  CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, body TEXT NOT NULL)`);

const dataDir = join(import.meta.dir, "data");
if (existsSync(dataDir)) {
  const insert = db.prepare("INSERT OR REPLACE INTO data (entity, key, value, body) VALUES (?, ?, ?, ?)");
  for (const name of readdirSync(dataDir).filter((n) => n.endsWith(".json"))) {
    const file = JSON.parse(readFileSync(join(dataDir, name), "utf8"));
    const entity = String(file.entity ?? name.replace(/\.json$/, ""));
    for (const r of file.records ?? [])
      insert.run(entity, String(r.key), String(r.value ?? r.key), JSON.stringify(r));
  }
}

const publicDir = realpathSync(join(import.meta.dir, "public"));
const NAME = /^[a-z0-9-]{1,40}$/;

const server = Bun.serve({
  hostname: "127.0.0.1",
  port,
  async fetch(req) {
    const url = new URL(req.url);
    if (!/^(127\.0\.0\.1|localhost):\d+$/.test(req.headers.get("host") ?? "")) {
      return new Response("forbidden host", { status: 403 });
    }
    // Migrated records: GET /api/data/<entity> lists them, /api/data/<entity>/<value> gives one.
    if (url.pathname.startsWith("/api/data/")) {
      const [entity, value] = url.pathname.slice("/api/data/".length).split("/").map(decodeURIComponent);
      if (!entity || !NAME.test(entity)) return new Response("bad entity", { status: 400 });
      if (value === undefined) {
        const rows = db.query("SELECT body FROM data WHERE entity = ? ORDER BY rowid").all(entity) as {
          body: string;
        }[];
        return Response.json(rows.map((r) => JSON.parse(r.body)));
      }
      const row = db
        .query("SELECT body FROM data WHERE entity = ? AND (value = ? OR key = ?)")
        .get(entity, value, value) as { body: string } | null;
      return row ? Response.json(JSON.parse(row.body)) : new Response("not found", { status: 404 });
    }
    if (url.pathname.startsWith("/api/records/")) {
      const kind = url.pathname.slice("/api/records/".length);
      if (!NAME.test(kind)) return new Response("bad kind", { status: 400 });
      if (req.method === "POST") {
        const body = await req.text();
        if (body.length > 100_000) return new Response("too large", { status: 413 });
        return Response.json(
          db.query("INSERT INTO records (kind, body) VALUES (?, ?) RETURNING id").get(kind, body),
        );
      }
      return Response.json(db.query("SELECT id, body FROM records WHERE kind = ? ORDER BY id").all(kind));
    }
    // The legacy app's addresses keep working: any path that is not a file of the app opens the shell, whose
    // router picks the screen.
    const shell = new Response(Bun.file(join(publicDir, "index.html")));
    if (url.pathname === "/") return shell;
    let real: string;
    try {
      real = realpathSync(join(publicDir, decodeURIComponent(url.pathname)));
    } catch {
      return shell;
    }
    if (!real.startsWith(publicDir + sep) || !statSync(real).isFile()) return shell;
    return new Response(Bun.file(real));
  },
});
console.log(`listening on http://127.0.0.1:${server.port}`);
